import 'package:flutter/material.dart';
import 'Accueil.dart';
import 'Services.dart';
class DashboardScreen extends StatefulWidget { const DashboardScreen({super.key}); @override State<DashboardScreen> createState() => _DashboardScreenState(); }
class _DashboardScreenState extends State<DashboardScreen> { int _selectedIndex = 0; final List<Widget> pages = [const Accueil(), const Services()]; void _onItemTapped(int index) => setState(() => _selectedIndex = index); @override Widget build(BuildContext context) => Scaffold(body: pages[_selectedIndex], bottomNavigationBar: BottomNavigationBar(currentIndex: _selectedIndex, onTap: _onItemTapped, type: BottomNavigationBarType.fixed, selectedItemColor: Colors.blue, unselectedItemColor: Colors.grey, selectedLabelStyle: const TextStyle(fontWeight: FontWeight.bold), unselectedLabelStyle: const TextStyle(fontWeight: FontWeight.normal), items: const [BottomNavigationBarItem(icon: Icon(Icons.home), label: 'Accueil'), BottomNavigationBarItem(icon: Icon(Icons.business), label: 'Services')])); }
